public function cancelledPaidOrderRefundsAmountAfterDiscount(): void
{
    $order = $this->draftOrder();
    $order->addItem(ProductId::generate(), 2, $this->czk(500_00));
    $order->applyDiscount($this->czk(150_00));
    $order->confirm();
    $order->markPaid();
    $order->releaseEvents();

    $order->cancel('customer request', new \DateTimeImmutable());

    self::assertTrue($order->refunded->equals($this->czk(850_00)));
    $event = $order->releaseEvents()[0];
    self::assertInstanceOf(OrderCancelled::class, $event);
    self::assertTrue($event->refund->equals($this->czk(850_00)));
}

