public function customerCancelsPaidOrderAndGetsMoneyBack(): void
{
    $this->loginAs('alice@example.com');
    $stockItems = self::getContainer()->get(StockItemRepository::class);
    $keyboard = ProductId::fromString(Catalog::KEYBOARD);

    $this->client->request('GET', '/objednavky');
    $this->client->submitForm('Nová objednávka');
    $this->client->followRedirect();
    $this->client->submitForm('Přidat', ['productId' => Catalog::KEYBOARD, 'quantity' => 2]);
    $this->client->followRedirect();
    $this->client->submitForm('Potvrdit objednávku');
    $this->client->followRedirect();
    $this->client->submitForm('Zaplatit');
    $this->client->followRedirect();
    self::assertSame(8, $stockItems->get($keyboard)->available());

    $this->client->submitForm('Stornovat objednávku');
    $this->client->followRedirect();

    self::assertSelectorTextContains('strong', 'cancelled');
    $order = $this->orderFromUrl();
    self::assertSame(OrderStatus::Cancelled, $order->status);
    self::assertTrue($order->refunded->equals($order->paidAmount()));
    self::assertSame(1000_00, $order->refunded->amountInCents);
    self::assertSame(10, $stockItems->get($keyboard)->available());
}

